#include "libbm25.h"

#include <limits.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifndef KC_BM25_BUILD_VERSION
#define KC_BM25_BUILD_VERSION 0
#endif

#define KC_BM25_DEFAULT_LIMIT 10U

typedef struct {
    char *id;
    char *content;
    uint32_t length;
} kc_bm25_document_t;

typedef struct {
    char *value;
    size_t start;
    size_t count;
} kc_bm25_term_t;

typedef struct {
    uint32_t ordinal;
    uint32_t frequency;
} kc_bm25_posting_t;

typedef struct {
    char *value;
    uint32_t ordinal;
} kc_bm25_occurrence_t;

typedef struct {
    kc_bm25_occurrence_t *items;
    size_t count;
    size_t capacity;
    uint32_t *lengths;
    uint32_t ordinal;
} kc_bm25_builder_t;

typedef struct {
    char **items;
    size_t count;
    size_t capacity;
} kc_bm25_query_t;

typedef struct {
    uint32_t ordinal;
    double score;
    int occupied;
} kc_bm25_accumulator_t;

struct kc_bm25 {
    kc_bm25_document_t *documents;
    size_t document_count;
    size_t document_capacity;
    kc_bm25_term_t *terms;
    size_t term_count;
    kc_bm25_posting_t *postings;
    size_t posting_count;
    uint64_t total_tokens;
    int fold_accents;
    int built;
    int read_only;
};

typedef struct {
    uint32_t first;
    uint32_t last;
} kc_bm25_range_t;

typedef struct {
    uint32_t codepoint;
    uint32_t offset;
    uint8_t count;
} kc_bm25_fold_t;

