/**
 * Grow a dynamic array while checking size arithmetic.
 * @param ptr Array allocation to resize.
 * @param capacity Current capacity, updated on success.
 * @param needed Required number of elements.
 * @param unit Bytes per element.
 * @return KC_BM25_OK or KC_BM25_ENOMEM.
 */
static int kc_bm25_grow(void **ptr, size_t *capacity, size_t needed, size_t unit) {
    size_t next = *capacity;
    void *memory;

    if (needed <= next) return KC_BM25_OK;
    if (unit == 0 || needed > SIZE_MAX / unit) return KC_BM25_ENOMEM;
    if (next == 0) next = 16;
    while (next < needed) {
        if (next > SIZE_MAX / 2) {
            next = needed;
            break;
        }
        next *= 2;
    }
    if (next > SIZE_MAX / unit) return KC_BM25_ENOMEM;
    memory = realloc(*ptr, next * unit);
    if (memory == NULL) return KC_BM25_ENOMEM;
    *ptr = memory;
    *capacity = next;
    return KC_BM25_OK;
}

/**
 * Copy a length-bounded string and terminate it.
 * @param text Source bytes.
 * @param length Number of bytes to copy.
 * @return Allocated string, or NULL on allocation failure.
 */
static char *kc_bm25_copy(const char *text, size_t length) {
    char *copy;

    if (length == SIZE_MAX) return NULL;
    copy = (char *)malloc(length + 1);
    if (copy == NULL) return NULL;
    memcpy(copy, text, length);
    copy[length] = '\0';
    return copy;
}

/**
 * Check membership in a sorted table of Unicode ranges.
 * @param ranges Range table.
 * @param count Number of ranges.
 * @param codepoint Unicode scalar.
 * @return 1 when the scalar belongs to a range, otherwise 0.
 */
static int kc_bm25_in_ranges(const kc_bm25_range_t *ranges,
    size_t count, uint32_t codepoint)
{
    size_t lo = 0;
    size_t hi = count;

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (codepoint < ranges[mid].first) hi = mid;
        else if (codepoint > ranges[mid].last) lo = mid + 1;
        else return 1;
    }
    return 0;
}

/**
 * Decode one UTF-8 scalar without accepting overlong or surrogate sequences.
 * @param text Input bytes.
 * @param size Input byte count.
 * @param offset Current byte offset, updated on success.
 * @param codepoint Receives a decoded scalar.
 * @return KC_BM25_OK, or KC_BM25_EUTF8 for malformed input.
 */
static int kc_bm25_decode(const char *text, size_t size,
    size_t *offset, uint32_t *codepoint)
{
    const unsigned char *data = (const unsigned char *)text;
    size_t pos = *offset;
    unsigned char first;
    uint32_t value;
    uint32_t minimum;
    size_t tail;

    if (pos >= size) return KC_BM25_EUTF8;
    first = data[pos];
    if (first <= 0x7F) {
        *codepoint = first;
        *offset = pos + 1;
        return KC_BM25_OK;
    }
    if (first >= 0xC2 && first <= 0xDF) {
        value = first & 0x1FU;
        minimum = 0x80;
        tail = 1;
    } else if (first >= 0xE0 && first <= 0xEF) {
        value = first & 0x0FU;
        minimum = 0x800;
        tail = 2;
    } else if (first >= 0xF0 && first <= 0xF4) {
        value = first & 0x07U;
        minimum = 0x10000;
        tail = 3;
    } else return KC_BM25_EUTF8;

    if (size - pos <= tail) return KC_BM25_EUTF8;
    for (size_t i = 1; i <= tail; i++) {
        if ((data[pos + i] & 0xC0U) != 0x80U) return KC_BM25_EUTF8;
        value = (value << 6) | (data[pos + i] & 0x3FU);
    }
    if (value < minimum || value > 0x10FFFF ||
        (value >= 0xD800 && value <= 0xDFFF))
        return KC_BM25_EUTF8;

    *codepoint = value;
    *offset = pos + tail + 1;
    return KC_BM25_OK;
}

/**
 * Validate all scalars in a UTF-8 string.
 * @param text NUL-terminated UTF-8 input.
 * @return KC_BM25_OK or KC_BM25_EUTF8.
 */
static int kc_bm25_validate_utf8(const char *text) {
    size_t size = strlen(text);
    size_t offset = 0;
    uint32_t codepoint;

    while (offset < size) {
        if (kc_bm25_decode(text, size, &offset, &codepoint) != KC_BM25_OK)
            return KC_BM25_EUTF8;
    }
    return KC_BM25_OK;
}

/**
 * Encode a scalar in UTF-8.
 * @param codepoint Unicode scalar.
 * @param out Output buffer of at least four bytes.
 * @return Number of encoded bytes.
 */
static size_t kc_bm25_encode(uint32_t codepoint, char *out) {
    if (codepoint < 0x80) {
        out[0] = (char)codepoint;
        return 1;
    }
    if (codepoint < 0x800) {
        out[0] = (char)(0xC0 | (codepoint >> 6));
        out[1] = (char)(0x80 | (codepoint & 0x3F));
        return 2;
    }
    if (codepoint < 0x10000) {
        out[0] = (char)(0xE0 | (codepoint >> 12));
        out[1] = (char)(0x80 | ((codepoint >> 6) & 0x3F));
        out[2] = (char)(0x80 | (codepoint & 0x3F));
        return 3;
    }
    out[0] = (char)(0xF0 | (codepoint >> 18));
    out[1] = (char)(0x80 | ((codepoint >> 12) & 0x3F));
    out[2] = (char)(0x80 | ((codepoint >> 6) & 0x3F));
    out[3] = (char)(0x80 | (codepoint & 0x3F));
    return 4;
}

/**
 * Find the lowercase NFD representation of a Unicode scalar.
 * @param codepoint Unicode scalar.
 * @param temp Temporary storage used for Hangul decomposition.
 * @param out Receives the normalized sequence, or NULL for unchanged scalars.
 * @param count Receives the normalized sequence length.
 * @return None.
 */
static void kc_bm25_fold(uint32_t codepoint, uint32_t temp[3],
    const uint32_t **out, size_t *count)
{
    size_t lo = 0;
    size_t hi = sizeof(kc_bm25_folds) / sizeof(kc_bm25_folds[0]);

    if (codepoint >= 0xAC00 && codepoint <= 0xD7A3) {
        uint32_t index = codepoint - 0xAC00;
        uint32_t t = index % 28;

        temp[0] = 0x1100 + index / 588;
        temp[1] = 0x1161 + (index % 588) / 28;
        temp[2] = 0x11A7 + t;
        *out = temp;
        *count = t == 0 ? 2 : 3;
        return;
    }
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (codepoint < kc_bm25_folds[mid].codepoint) hi = mid;
        else if (codepoint > kc_bm25_folds[mid].codepoint) lo = mid + 1;
        else {
            *out = kc_bm25_fold_values + kc_bm25_folds[mid].offset;
            *count = kc_bm25_folds[mid].count;
            return;
        }
    }
    *out = NULL;
    *count = 0;
}

/**
 * Finish and deliver one lexical token.
 * @param word Reusable token buffer.
 * @param length Current token length, reset after delivery.
 * @param visit Called for every emitted token.
 * @param context Callback context.
 * @return Callback status or KC_BM25_OK.
 */
static int kc_bm25_flush(char *word, size_t *length,
    int (*visit)(void *, const char *), void *context)
{
    int result;

    if (*length == 0) return KC_BM25_OK;
    word[*length] = '\0';
    result = visit(context, word);
    *length = 0;
    return result;
}

/**
 * Tokenize UTF-8 text with the fixed Unicode analyzer.
 * @param text Input text.
 * @param accents Whether combining marks are removed.
 * @param visit Called with every normalized lexical token.
 * @param context Callback context.
 * @return KC_BM25_OK or an error code.
 */
static int kc_bm25_analyze(const char *text, int accents,
    int (*visit)(void *, const char *), void *context)
{
    char *word = NULL;
    size_t capacity = 0;
    size_t length = 0;
    size_t size = strlen(text);
    size_t offset = 0;
    int status = KC_BM25_OK;

    while (offset < size) {
        uint32_t cp;
        uint32_t temp[3];
        const uint32_t *sequence;
        size_t count;
        int rc = kc_bm25_decode(text, size, &offset, &cp);

        if (rc != KC_BM25_OK) {
            status = rc;
            break;
        }
        kc_bm25_fold(cp, temp, &sequence, &count);
        if (sequence == NULL) {
            sequence = &cp;
            count = 1;
        }
        for (size_t i = 0; i < count; i++) {
            uint32_t item = sequence[i];
            int is_word = kc_bm25_in_ranges(kc_bm25_word_ranges,
                sizeof(kc_bm25_word_ranges) / sizeof(kc_bm25_word_ranges[0]),
                item);
            int is_mark = kc_bm25_in_ranges(kc_bm25_mark_ranges,
                sizeof(kc_bm25_mark_ranges) / sizeof(kc_bm25_mark_ranges[0]),
                item);

            if (is_mark && accents) continue;
            if (!is_word) {
                status = kc_bm25_flush(word, &length, visit, context);
                if (status != KC_BM25_OK) goto done;
                continue;
            }
            if (length > SIZE_MAX - 5) {
                status = KC_BM25_ENOMEM;
                goto done;
            }
            status = kc_bm25_grow((void **)&word, &capacity,
                length + 5, sizeof(char));
            if (status != KC_BM25_OK) goto done;
            length += kc_bm25_encode(item, word + length);
        }
    }
    if (status == KC_BM25_OK)
        status = kc_bm25_flush(word, &length, visit, context);

done:
    free(word);
    return status;
}

/**
 * Append an occurrence while computing its document length.
 * @param context Build-stage accumulator.
 * @param token Normalized lexical token.
 * @return KC_BM25_OK or an error status.
 */
static int kc_bm25_collect(void *context, const char *token) {
    kc_bm25_builder_t *builder = (kc_bm25_builder_t *)context;
    kc_bm25_occurrence_t item;
    int status;

    if (builder->lengths[builder->ordinal] == UINT32_MAX)
        return KC_BM25_ENOMEM;
    item.value = kc_bm25_copy(token, strlen(token));
    if (item.value == NULL) return KC_BM25_ENOMEM;
    status = kc_bm25_grow((void **)&builder->items, &builder->capacity,
        builder->count + 1, sizeof(*builder->items));
    if (status != KC_BM25_OK) {
        free(item.value);
        return status;
    }
    item.ordinal = builder->ordinal;
    builder->items[builder->count++] = item;
    builder->lengths[builder->ordinal]++;
    return KC_BM25_OK;
}

/**
 * Compare occurrences by normalized token and then ordinal.
 * @param a First occurrence.
 * @param b Second occurrence.
 * @return Negative, zero, or positive comparison result.
 */
static int kc_bm25_occurrence_compare(const void *a, const void *b) {
    const kc_bm25_occurrence_t *left = (const kc_bm25_occurrence_t *)a;
    const kc_bm25_occurrence_t *right = (const kc_bm25_occurrence_t *)b;
    int cmp = strcmp(left->value, right->value);

    if (cmp != 0) return cmp;
    if (left->ordinal < right->ordinal) return -1;
    if (left->ordinal > right->ordinal) return 1;
    return 0;
}

/**
 * Free a complete inverted index without touching its source documents.
 * @param index Index to clear.
 * @return None.
 */
static void kc_bm25_clear_postings(kc_bm25_t *index) {
    for (size_t i = 0; i < index->term_count; i++)
        free(index->terms[i].value);
    free(index->terms);
    free(index->postings);
    index->terms = NULL;
    index->postings = NULL;
    index->term_count = 0;
    index->posting_count = 0;
    index->total_tokens = 0;
    index->built = 0;
}

/**
 * Create an empty index with optional analyzer configuration.
 * @param out Receives the new index.
 * @param options Optional analyzer configuration.
 * @return KC_BM25_OK or an error status.
 */
int kc_bm25_open(kc_bm25_t **out, const kc_bm25_options_t *options) {
    kc_bm25_t *index;
    int accents = 0;

    if (out == NULL) return KC_BM25_EINVAL;
    *out = NULL;
    if (options != NULL && options->fold_accents != NULL) {
        accents = *options->fold_accents;
        if (accents != 0 && accents != 1) return KC_BM25_EINVAL;
    }
    index = (kc_bm25_t *)calloc(1, sizeof(*index));
    if (index == NULL) return KC_BM25_ENOMEM;
    index->fold_accents = accents;
    *out = index;
    return KC_BM25_OK;
}

/**
 * Add a UTF-8 document, copying its ID and contents into the index.
 * @param index Writable index.
 * @param id Nonempty public ID.
 * @param content Document text.
 * @return KC_BM25_OK or an error status.
 */
int kc_bm25_add(kc_bm25_t *index, const char *id, const char *content) {
    kc_bm25_document_t item;
    int status;

    if (index == NULL || id == NULL || id[0] == '\0' || content == NULL)
        return KC_BM25_EINVAL;
    if (index->read_only) return KC_BM25_ESTATE;
    if (index->document_count >= UINT32_MAX) return KC_BM25_ENOMEM;
    if ((status = kc_bm25_validate_utf8(id)) != KC_BM25_OK) return status;
    if ((status = kc_bm25_validate_utf8(content)) != KC_BM25_OK) return status;
    item.id = kc_bm25_copy(id, strlen(id));
    if (item.id == NULL) return KC_BM25_ENOMEM;
    item.content = kc_bm25_copy(content, strlen(content));
    if (item.content == NULL) {
        free(item.id);
        return KC_BM25_ENOMEM;
    }
    item.length = 0;
    status = kc_bm25_grow((void **)&index->documents,
        &index->document_capacity, index->document_count + 1,
        sizeof(*index->documents));
    if (status != KC_BM25_OK) {
        free(item.id);
        free(item.content);
        return status;
    }
    if (index->built) kc_bm25_clear_postings(index);
    index->documents[index->document_count++] = item;
    return KC_BM25_OK;
}

/**
 * Build a sorted dictionary and per-term postings for all documents.
 * @param index Writable index.
 * @return KC_BM25_OK or an error status.
 */
int kc_bm25_build(kc_bm25_t *index) {
    kc_bm25_builder_t builder = {0};
    kc_bm25_term_t *terms = NULL;
    kc_bm25_posting_t *postings = NULL;
    size_t term_count = 0, term_capacity = 0;
    size_t posting_count = 0, posting_capacity = 0;
    uint64_t total = 0;
    int status = KC_BM25_OK;

    if (index == NULL) return KC_BM25_EINVAL;
    if (index->read_only) return KC_BM25_ESTATE;
    if (index->document_count > 0) {
        builder.lengths = (uint32_t *)calloc(index->document_count,
            sizeof(*builder.lengths));
        if (builder.lengths == NULL) return KC_BM25_ENOMEM;
    }

    for (size_t i = 0; i < index->document_count; i++) {
        builder.ordinal = (uint32_t)i;
        status = kc_bm25_analyze(index->documents[i].content,
            index->fold_accents, kc_bm25_collect, &builder);
        if (status != KC_BM25_OK) goto failed;
        total += builder.lengths[i];
    }
    qsort(builder.items, builder.count, sizeof(*builder.items),
        kc_bm25_occurrence_compare);

    for (size_t i = 0; i < builder.count; i++) {
        kc_bm25_occurrence_t *item = &builder.items[i];
        kc_bm25_term_t *term;
        kc_bm25_posting_t *posting;

        if (term_count == 0 ||
            strcmp(terms[term_count - 1].value, item->value) != 0)
        {
            status = kc_bm25_grow((void **)&terms, &term_capacity,
                term_count + 1, sizeof(*terms));
            if (status != KC_BM25_OK) goto failed;
            term = &terms[term_count];
            term->value = kc_bm25_copy(item->value, strlen(item->value));
            if (term->value == NULL) {
                status = KC_BM25_ENOMEM;
                goto failed;
            }
            term->start = posting_count;
            term->count = 0;
            term_count++;
        }
        term = &terms[term_count - 1];
        if (term->count > 0 &&
            postings[posting_count - 1].ordinal == item->ordinal)
        {
            posting = &postings[posting_count - 1];
            if (posting->frequency == UINT32_MAX) {
                status = KC_BM25_ENOMEM;
                goto failed;
            }
            posting->frequency++;
        } else {
            status = kc_bm25_grow((void **)&postings, &posting_capacity,
                posting_count + 1, sizeof(*postings));
            if (status != KC_BM25_OK) goto failed;
            posting = &postings[posting_count++];
            posting->ordinal = item->ordinal;
            posting->frequency = 1;
            term->count++;
        }
    }

    kc_bm25_clear_postings(index);
    index->terms = terms;
    index->term_count = term_count;
    index->postings = postings;
    index->posting_count = posting_count;
    index->total_tokens = total;
    index->built = 1;
    for (size_t i = 0; i < index->document_count; i++)
        index->documents[i].length = builder.lengths[i];
    terms = NULL;
    postings = NULL;

failed:
    for (size_t i = 0; i < builder.count; i++)
        free(builder.items[i].value);
    free(builder.items);
    free(builder.lengths);
    for (size_t i = 0; i < term_count; i++)
        free(terms == NULL ? NULL : terms[i].value);
    free(terms);
    free(postings);
    return status;
}

/**
 * Collect one distinct-query candidate before deduplication.
 * @param context Query collector.
 * @param token Normalized query token.
 * @return KC_BM25_OK or an error status.
 */
static int kc_bm25_query_collect(void *context, const char *token) {
    kc_bm25_query_t *query = (kc_bm25_query_t *)context;
    char *copy = kc_bm25_copy(token, strlen(token));
    int status;

    if (copy == NULL) return KC_BM25_ENOMEM;
    status = kc_bm25_grow((void **)&query->items, &query->capacity,
        query->count + 1, sizeof(*query->items));
    if (status != KC_BM25_OK) {
        free(copy);
        return status;
    }
    query->items[query->count++] = copy;
    return KC_BM25_OK;
}

/**
 * Compare two pointers to lexical terms.
 * @param a First term pointer.
 * @param b Second term pointer.
 * @return Lexicographical comparison result.
 */
static int kc_bm25_string_compare(const void *a, const void *b) {
    const char *const *left = (const char *const *)a;
    const char *const *right = (const char *const *)b;

    return strcmp(*left, *right);
}

/**
 * Find a term's sorted inverted dictionary entry.
 * @param index Searchable index.
 * @param text Normalized term.
 * @return Term pointer or NULL when absent.
 */
static const kc_bm25_term_t *kc_bm25_find(const kc_bm25_t *index,
    const char *text)
{
    size_t lo = 0;
    size_t hi = index->term_count;

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        int cmp = strcmp(text, index->terms[mid].value);

        if (cmp < 0) hi = mid;
        else if (cmp > 0) lo = mid + 1;
        else return &index->terms[mid];
    }
    return NULL;
}

typedef struct {
    kc_bm25_token_fn visit;
    void *userdata;
} kc_bm25_token_context_t;

/**
 * Adapt token callbacks to the private Unicode analyzer.
 * @param context Visitor and its context.
 * @param token Borrowed normalized token.
 * @return KC_BM25_OK or KC_BM25_EABORT.
 */
static int kc_bm25_token_visit(void *context, const char *token)
{
    kc_bm25_token_context_t *adapter =
        (kc_bm25_token_context_t *)context;

    return adapter->visit(token, adapter->userdata) == 0 ?
        KC_BM25_OK : KC_BM25_EABORT;
}

/**
 * Traverse normalized text tokens according to the index's analyzer.
 * @param index Built or imported index.
 * @param text UTF-8 input.
 * @param visit Required visitor.
 * @param userdata Context forwarded unchanged.
 * @return KC_BM25_OK or an error code.
 */
int kc_bm25_tokens(const kc_bm25_t *index, const char *text,
    kc_bm25_token_fn visit, void *userdata)
{
    kc_bm25_token_context_t context = {visit, userdata};

    if (index == NULL || !index->built || text == NULL || visit == NULL)
        return KC_BM25_EINVAL;
    return kc_bm25_analyze(text, index->fold_accents,
        kc_bm25_token_visit, &context);
}

/**
 * Visit the unique normalized vocabulary, without copying term storage.
 * @param index Built or imported index.
 * @param visit Term callback.
 * @param userdata Caller data.
 * @return KC_BM25_OK or KC_BM25_EABORT.
 */
int kc_bm25_vocabulary(const kc_bm25_t *index,
    kc_bm25_word_fn visit, void *userdata)
{
    if (index == NULL || !index->built || visit == NULL)
        return KC_BM25_EINVAL;

    for (size_t i = 0; i < index->term_count; i++) {
        if (visit(index->terms[i].value, index->terms[i].count,
            userdata) != 0) return KC_BM25_EABORT;
    }
    return KC_BM25_OK;
}

/**
 * Visit document postings for a previously normalized vocabulary term.
 * @param index Built or imported index.
 * @param term Normalized term.
 * @param visit Posting visitor.
 * @param userdata Caller context.
 * @return KC_BM25_OK or KC_BM25_EABORT.
 */
int kc_bm25_postings(const kc_bm25_t *index, const char *term,
    kc_bm25_posting_fn visit, void *userdata)
{
    const kc_bm25_term_t *entry;

    if (index == NULL || !index->built || term == NULL || visit == NULL)
        return KC_BM25_EINVAL;
    entry = kc_bm25_find(index, term);
    if (entry == NULL) return KC_BM25_OK;

    for (size_t i = 0; i < entry->count; i++) {
        const kc_bm25_posting_t *posting =
            &index->postings[entry->start + i];

        if (visit(posting->ordinal, posting->frequency,
            userdata) != 0) return KC_BM25_EABORT;
    }
    return KC_BM25_OK;
}

/**
 * Insert one ordinal and score into a sparse candidate map.
 * @param table Map allocation.
 * @param capacity Current map capacity.
 * @param used Current number of candidates.
 * @param ordinal Document ordinal.
 * @param score Score contribution to add.
 * @return KC_BM25_OK or an error status.
 */
static int kc_bm25_accumulate(kc_bm25_accumulator_t **table,
    size_t *capacity, size_t *used, uint32_t ordinal, double score)
{
    size_t slot;

    if (*capacity == 0 || (*used + 1) > (*capacity / 2)) {
        size_t next = *capacity == 0 ? 32 : *capacity * 2;
        kc_bm25_accumulator_t *grown;

        if (next < *capacity || next > SIZE_MAX / sizeof(*grown))
            return KC_BM25_ENOMEM;
        grown = (kc_bm25_accumulator_t *)calloc(next, sizeof(*grown));
        if (grown == NULL) return KC_BM25_ENOMEM;
        for (size_t i = 0; i < *capacity; i++) {
            if ((*table)[i].occupied) {
                size_t j = ((uint64_t)(*table)[i].ordinal * 2654435761U)
                    & (next - 1);
                while (grown[j].occupied) j = (j + 1) & (next - 1);
                grown[j] = (*table)[i];
            }
        }
        free(*table);
        *table = grown;
        *capacity = next;
    }
    slot = ((uint64_t)ordinal * 2654435761U) & (*capacity - 1);
    while ((*table)[slot].occupied && (*table)[slot].ordinal != ordinal)
        slot = (slot + 1) & (*capacity - 1);
    if (!(*table)[slot].occupied) {
        (*table)[slot].occupied = 1;
        (*table)[slot].ordinal = ordinal;
        (*table)[slot].score = 0;
        (*used)++;
    }
    (*table)[slot].score += score;
    return KC_BM25_OK;
}

/**
 * Determine whether a result ranks better than another result.
 * @param a First result.
 * @param b Second result.
 * @return 1 when the first result has higher rank, otherwise 0.
 */
static int kc_bm25_better(const kc_bm25_result_t *a,
    const kc_bm25_result_t *b)
{
    if (a->score > b->score) return 1;
    if (a->score < b->score) return 0;
    return a->ordinal < b->ordinal;
}

/**
 * Restore the worst-first heap invariant after updating its root.
 * @param heap Result min-heap.
 * @param count Number of heap entries.
 * @return None.
 */
static void kc_bm25_heap_down(kc_bm25_result_t *heap, size_t count) {
    size_t root = 0;

    while (root <= count / 2) {
        size_t left = root * 2 + 1;
        size_t right = left + 1;
        size_t worst = root;
        kc_bm25_result_t swap;

        if (left < count && kc_bm25_better(&heap[worst], &heap[left]))
            worst = left;
        if (right < count && kc_bm25_better(&heap[worst], &heap[right]))
            worst = right;
        if (worst == root) break;
        swap = heap[root];
        heap[root] = heap[worst];
        heap[worst] = swap;
        root = worst;
    }
}

/**
 * Compare ranked results for final descending presentation.
 * @param a First result.
 * @param b Second result.
 * @return Negative when the first result ranks higher.
 */
static int kc_bm25_rank_compare(const void *a, const void *b) {
    const kc_bm25_result_t *left = (const kc_bm25_result_t *)a;
    const kc_bm25_result_t *right = (const kc_bm25_result_t *)b;

    if (kc_bm25_better(left, right)) return -1;
    if (kc_bm25_better(right, left)) return 1;
    return 0;
}

/**
 * Search the inverted index using positive-IDF Okapi BM25.
 * @param index Searchable index.
 * @param text UTF-8 query.
 * @param options Optional search configuration.
 * @param out_results Receives the result allocation.
 * @param out_count Receives the result count.
 * @return KC_BM25_OK or an error status.
 */
int kc_bm25_search(const kc_bm25_t *index, const char *text,
    const kc_bm25_search_options_t *options,
    kc_bm25_result_t **out_results, size_t *out_count)
{
    kc_bm25_query_t query = {0};
    kc_bm25_accumulator_t *candidates = NULL;
    kc_bm25_result_t *heap = NULL;
    size_t capacity = 0, used = 0, limit = KC_BM25_DEFAULT_LIMIT;
    size_t heap_size = 0;
    double k1 = 1.2, b = 0.75;
    double avgdl;
    int status;

    if (out_results != NULL) *out_results = NULL;
    if (out_count != NULL) *out_count = 0;
    if (index == NULL || text == NULL ||
        out_results == NULL || out_count == NULL) return KC_BM25_EINVAL;
    if (!index->built) return KC_BM25_ESTATE;
    if (options != NULL) {
        if (options->limit != NULL) limit = *options->limit;
        if (options->k1 != NULL) k1 = *options->k1;
        if (options->b != NULL) b = *options->b;
    }
    if (!isfinite(k1) || !isfinite(b) ||
        k1 < 0 || b < 0 || b > 1) return KC_BM25_EINVAL;
    status = kc_bm25_analyze(text, index->fold_accents,
        kc_bm25_query_collect, &query);
    if (status != KC_BM25_OK) goto done;
    if (query.count == 0 || limit == 0 ||
        index->document_count == 0 || index->total_tokens == 0)
        goto done;
    qsort(query.items, query.count, sizeof(*query.items),
        kc_bm25_string_compare);

    avgdl = (double)index->total_tokens / (double)index->document_count;
    for (size_t i = 0; i < query.count; i++) {
        const kc_bm25_term_t *term;
        double idf;

        if (i > 0 && strcmp(query.items[i], query.items[i - 1]) == 0)
            continue;
        term = kc_bm25_find(index, query.items[i]);
        if (term == NULL) continue;
        idf = log1p(((double)index->document_count - (double)term->count
            + 0.5) / ((double)term->count + 0.5));

        for (size_t j = 0; j < term->count; j++) {
            const kc_bm25_posting_t *posting =
                &index->postings[term->start + j];
            const kc_bm25_document_t *document =
                &index->documents[posting->ordinal];
            double tf = (double)posting->frequency;
            double denom = tf + k1 * (1.0 - b +
                b * ((double)document->length / avgdl));
            double score = idf * tf * (k1 + 1.0) / denom;

            status = kc_bm25_accumulate(&candidates, &capacity, &used,
                posting->ordinal, score);
            if (status != KC_BM25_OK) goto done;
        }
    }

    if (limit > used) limit = used;
    if (limit == 0) goto done;
    if (limit > SIZE_MAX / sizeof(*heap)) {
        status = KC_BM25_ENOMEM;
        goto done;
    }
    heap = (kc_bm25_result_t *)malloc(limit * sizeof(*heap));
    if (heap == NULL) {
        status = KC_BM25_ENOMEM;
        goto done;
    }

    for (size_t i = 0; i < capacity; i++) {
        kc_bm25_result_t item;
        size_t position;
        kc_bm25_result_t tmp;

        if (!candidates[i].occupied) continue;
        item.ordinal = candidates[i].ordinal;
        item.id = index->documents[item.ordinal].id;
        item.content = index->documents[item.ordinal].content;
        item.score = candidates[i].score;

        if (heap_size == limit) {
            if (!kc_bm25_better(&item, &heap[0])) continue;
            heap[0] = item;
            kc_bm25_heap_down(heap, heap_size);
            continue;
        }
        position = heap_size++;
        heap[position] = item;
        while (position > 0) {
            size_t parent = (position - 1) / 2;

            if (!kc_bm25_better(&heap[parent], &heap[position])) break;
            tmp = heap[parent];
            heap[parent] = heap[position];
            heap[position] = tmp;
            position = parent;
        }
    }

    qsort(heap, heap_size, sizeof(*heap), kc_bm25_rank_compare);
    *out_results = heap;
    *out_count = heap_size;
    heap = NULL;
    status = KC_BM25_OK;

done:
    for (size_t i = 0; i < query.count; i++) free(query.items[i]);
    free(query.items);
    free(candidates);
    free(heap);
    return status;
}

/**
 * Encode an unsigned 32-bit value in little-endian byte order.
 * @param out Four-byte destination.
 * @param value Integer to encode.
 * @return None.
 */
static void kc_bm25_write32(unsigned char *out, uint32_t value) {
    for (size_t i = 0; i < 4; i++) out[i] = (unsigned char)(value >> (8 * i));
}

/**
 * Encode an unsigned 64-bit value in little-endian byte order.
 * @param out Eight-byte destination.
 * @param value Integer to encode.
 * @return None.
 */
static void kc_bm25_write64(unsigned char *out, uint64_t value) {
    for (size_t i = 0; i < 8; i++) out[i] = (unsigned char)(value >> (8 * i));
}

/**
 * Decode an unsigned 32-bit value from little-endian bytes.
 * @param in Four-byte input.
 * @return Decoded integer.
 */
static uint32_t kc_bm25_read32(const unsigned char *in) {
    uint32_t value = 0;

    for (size_t i = 0; i < 4; i++)
        value |= (uint32_t)in[i] << (8 * i);
    return value;
}

/**
 * Decode an unsigned 64-bit value from little-endian bytes.
 * @param in Eight-byte input.
 * @return Decoded integer.
 */
static uint64_t kc_bm25_read64(const unsigned char *in) {
    uint64_t value = 0;

    for (size_t i = 0; i < 8; i++)
        value |= (uint64_t)in[i] << (8 * i);
    return value;
}

typedef struct {
    unsigned char *cursor;
    size_t remaining;
} kc_bm25_writer_t;

typedef struct {
    const unsigned char *cursor;
    size_t remaining;
} kc_bm25_reader_t;

/**
 * Write bytes within an allocated serialization buffer.
 * @param writer Output buffer and remaining space.
 * @param data Source bytes.
 * @param count Number of bytes.
 * @return KC_BM25_OK or KC_BM25_EFORMAT.
 */
static int kc_bm25_memwrite(kc_bm25_writer_t *writer,
    const void *data, size_t count)
{
    if (count > writer->remaining) return KC_BM25_EFORMAT;
    if (count > 0) memcpy(writer->cursor, data, count);
    writer->cursor += count;
    writer->remaining -= count;
    return KC_BM25_OK;
}

/**
 * Read bytes without exceeding the supplied serialization slice.
 * @param reader Input bytes and remaining length.
 * @param dest Destination buffer.
 * @param count Number of bytes.
 * @return KC_BM25_OK or KC_BM25_EFORMAT.
 */
static int kc_bm25_memread(kc_bm25_reader_t *reader,
    void *dest, size_t count)
{
    if (count > reader->remaining) return KC_BM25_EFORMAT;
    if (count > 0) memcpy(dest, reader->cursor, count);
    reader->cursor += count;
    reader->remaining -= count;
    return KC_BM25_OK;
}

/**
 * Add a serialization field length with overflow protection.
 * @param total Current length, updated after success.
 * @param extra Additional byte count.
 * @return KC_BM25_OK or KC_BM25_ENOMEM.
 */
static int kc_bm25_size_add(size_t *total, size_t extra)
{
    if (extra > SIZE_MAX - *total) return KC_BM25_ENOMEM;
    *total += extra;
    return KC_BM25_OK;
}

/**
 * Export a built index to an owned portable binary byte buffer.
 * @param index Built index.
 * @param out Receives the allocated bytes.
 * @param out_size Receives the exact byte count.
 * @return KC_BM25_OK or an error status.
 */
int kc_bm25_export(const kc_bm25_t *index,
    void **out, size_t *out_size)
{
    unsigned char header[44] = {0};
    unsigned char data[24];
    unsigned char *bytes;
    kc_bm25_writer_t writer;
    size_t size = sizeof(header);
    int status = KC_BM25_OK;

    if (out != NULL) *out = NULL;
    if (out_size != NULL) *out_size = 0;
    if (index == NULL || out == NULL || out_size == NULL)
        return KC_BM25_EINVAL;
    if (!index->built) return KC_BM25_ESTATE;
    for (size_t i = 0; i < index->document_count; i++) {
        const kc_bm25_document_t *document = &index->documents[i];

        if ((status = kc_bm25_size_add(&size, 24)) != KC_BM25_OK ||
            (status = kc_bm25_size_add(&size, strlen(document->id))) != KC_BM25_OK ||
            (status = kc_bm25_size_add(&size, strlen(document->content))) != KC_BM25_OK)
            return status;
    }
    for (size_t i = 0; i < index->term_count; i++) {
        if ((status = kc_bm25_size_add(&size, 24)) != KC_BM25_OK ||
            (status = kc_bm25_size_add(&size, strlen(index->terms[i].value))) != KC_BM25_OK)
            return status;
    }
    if (index->posting_count > (SIZE_MAX - size) / 8)
        return KC_BM25_ENOMEM;
    size += index->posting_count * 8;

    bytes = (unsigned char *)malloc(size);
    if (bytes == NULL) return KC_BM25_ENOMEM;
    writer.cursor = bytes;
    writer.remaining = size;

    memcpy(header, "KCBM25\0", 8);
    kc_bm25_write32(header + 8, (uint32_t)index->fold_accents);
    kc_bm25_write64(header + 12, (uint64_t)index->document_count);
    kc_bm25_write64(header + 20, (uint64_t)index->term_count);
    kc_bm25_write64(header + 28, (uint64_t)index->posting_count);
    kc_bm25_write64(header + 36, index->total_tokens);
    status = kc_bm25_memwrite(&writer, header, sizeof(header));
    for (size_t i = 0; status == KC_BM25_OK &&
        i < index->document_count; i++)
    {
        const kc_bm25_document_t *document = &index->documents[i];
        size_t id_len = strlen(document->id);
        size_t text_len = strlen(document->content);

        kc_bm25_write64(data, (uint64_t)id_len);
        kc_bm25_write64(data + 8, (uint64_t)text_len);
        kc_bm25_write64(data + 16, (uint64_t)document->length);
        status = kc_bm25_memwrite(&writer, data, 24);
        if (status == KC_BM25_OK)
            status = kc_bm25_memwrite(&writer, document->id, id_len);
        if (status == KC_BM25_OK)
            status = kc_bm25_memwrite(&writer, document->content, text_len);
    }
    for (size_t i = 0; status == KC_BM25_OK && i < index->term_count; i++) {
        const kc_bm25_term_t *term = &index->terms[i];
        size_t len = strlen(term->value);

        kc_bm25_write64(data, (uint64_t)len);
        kc_bm25_write64(data + 8, (uint64_t)term->start);
        kc_bm25_write64(data + 16, (uint64_t)term->count);
        status = kc_bm25_memwrite(&writer, data, 24);
        if (status == KC_BM25_OK)
            status = kc_bm25_memwrite(&writer, term->value, len);
    }
    for (size_t i = 0; status == KC_BM25_OK &&
        i < index->posting_count; i++)
    {
        kc_bm25_write32(data, index->postings[i].ordinal);
        kc_bm25_write32(data + 4, index->postings[i].frequency);
        status = kc_bm25_memwrite(&writer, data, 8);
    }
    if (status != KC_BM25_OK || writer.remaining != 0) {
        free(bytes);
        return status == KC_BM25_OK ? KC_BM25_EFORMAT : status;
    }
    *out = bytes;
    *out_size = size;
    return KC_BM25_OK;
}

/**
 * Import a portable index directly from an immutable memory slice.
 * Source bytes need remain valid only for the duration of this call.
 * @param out Receives the loaded read-only index.
 * @param data Serialized index bytes.
 * @param size Length of the memory slice.
 * @return KC_BM25_OK or an error status.
 */
int kc_bm25_import(kc_bm25_t **out, const void *data, size_t size)
{
    unsigned char head[44], item[24];
    kc_bm25_reader_t reader = {(const unsigned char *)data, size};
    kc_bm25_t *index = NULL;
    uint64_t docs, terms, postings, total, lengths_total = 0;
    uint64_t *lengths = NULL;
    uint64_t offset = 0;
    int status = KC_BM25_EFORMAT;
    int accents;

    if (out == NULL) return KC_BM25_EINVAL;
    *out = NULL;
    if (data == NULL) return KC_BM25_EINVAL;
    if (kc_bm25_memread(&reader, head, sizeof(head)) != KC_BM25_OK)
        goto failed;
    if (memcmp(head, "KCBM25\0", 8) != 0) goto failed;

    accents = (int)kc_bm25_read32(head + 8);
    docs = kc_bm25_read64(head + 12);
    terms = kc_bm25_read64(head + 20);
    postings = kc_bm25_read64(head + 28);
    total = kc_bm25_read64(head + 36);
    if ((accents != 0 && accents != 1) || docs > UINT32_MAX ||
        docs > SIZE_MAX / sizeof(kc_bm25_document_t) ||
        terms > SIZE_MAX / sizeof(kc_bm25_term_t) ||
        postings > SIZE_MAX / sizeof(kc_bm25_posting_t) ||
        docs > reader.remaining / 24 ||
        terms > reader.remaining / 24 ||
        postings > reader.remaining / 8 ||
        (docs == 0 && (terms != 0 || postings != 0 || total != 0)) ||
        postings < terms)
        goto failed;
    {
        kc_bm25_options_t options = {&accents};

        status = kc_bm25_open(&index, &options);
        if (status != KC_BM25_OK) goto failed;
    }
    status = KC_BM25_EFORMAT;
    if (docs != 0) {
        index->documents = (kc_bm25_document_t *)calloc((size_t)docs,
            sizeof(*index->documents));
        lengths = (uint64_t *)calloc((size_t)docs, sizeof(*lengths));
        if (index->documents == NULL || lengths == NULL) {
            status = KC_BM25_ENOMEM;
            goto failed;
        }
        index->document_capacity = (size_t)docs;
    }
    for (uint64_t i = 0; i < docs; i++) {
        uint64_t id_len, text_len, length;
        kc_bm25_document_t *document = &index->documents[i];

        if (kc_bm25_memread(&reader, item, 24) != KC_BM25_OK)
            goto failed;
        id_len = kc_bm25_read64(item);
        text_len = kc_bm25_read64(item + 8);
        length = kc_bm25_read64(item + 16);
        if (id_len == 0 || id_len >= SIZE_MAX || text_len >= SIZE_MAX ||
            length > UINT32_MAX || id_len > reader.remaining ||
            text_len > reader.remaining - id_len ||
            length > total - lengths_total)
            goto failed;

        index->document_count++;
        document->id = (char *)malloc((size_t)id_len + 1);
        document->content = (char *)malloc((size_t)text_len + 1);
        if (document->id == NULL || document->content == NULL) {
            status = KC_BM25_ENOMEM;
            goto failed;
        }
        if (kc_bm25_memread(&reader, document->id,
            (size_t)id_len) != KC_BM25_OK ||
            kc_bm25_memread(&reader, document->content,
            (size_t)text_len) != KC_BM25_OK)
            goto failed;
        if (memchr(document->id, 0, (size_t)id_len) != NULL ||
            memchr(document->content, 0, (size_t)text_len) != NULL)
            goto failed;
        document->id[id_len] = '\0';
        document->content[text_len] = '\0';
        if (kc_bm25_validate_utf8(document->id) != KC_BM25_OK ||
            kc_bm25_validate_utf8(document->content) != KC_BM25_OK)
            goto failed;
        document->length = (uint32_t)length;
        lengths_total += length;
    }
    if (lengths_total != total) goto failed;

    if (terms != 0) {
        index->terms = (kc_bm25_term_t *)calloc((size_t)terms,
            sizeof(*index->terms));
        if (index->terms == NULL) {
            status = KC_BM25_ENOMEM;
            goto failed;
        }
    }
    for (uint64_t i = 0; i < terms; i++) {
        uint64_t length, start, count;
        kc_bm25_term_t *term = &index->terms[i];

        if (kc_bm25_memread(&reader, item, 24) != KC_BM25_OK)
            goto failed;
        length = kc_bm25_read64(item);
        start = kc_bm25_read64(item + 8);
        count = kc_bm25_read64(item + 16);
        if (length == 0 || length >= SIZE_MAX || length > reader.remaining ||
            start != offset || count == 0 || count > docs ||
            count > postings - offset)
            goto failed;

        index->term_count++;
        term->value = (char *)malloc((size_t)length + 1);
        if (term->value == NULL) {
            status = KC_BM25_ENOMEM;
            goto failed;
        }
        if (kc_bm25_memread(&reader, term->value,
            (size_t)length) != KC_BM25_OK)
            goto failed;
        if (memchr(term->value, 0, (size_t)length) != NULL)
            goto failed;
        term->value[length] = '\0';
        if (kc_bm25_validate_utf8(term->value) != KC_BM25_OK ||
            (i > 0 && strcmp(index->terms[i - 1].value, term->value) >= 0))
            goto failed;
        term->start = (size_t)start;
        term->count = (size_t)count;
        offset += count;
    }
    if (offset != postings) goto failed;

    if (postings != 0) {
        index->postings = (kc_bm25_posting_t *)calloc((size_t)postings,
            sizeof(*index->postings));
        if (index->postings == NULL) {
            status = KC_BM25_ENOMEM;
            goto failed;
        }
    }
    for (size_t i = 0; i < index->term_count; i++) {
        const kc_bm25_term_t *term = &index->terms[i];
        uint32_t previous = 0;

        for (size_t j = 0; j < term->count; j++) {
            kc_bm25_posting_t *posting = &index->postings[term->start + j];

            if (kc_bm25_memread(&reader, item, 8) != KC_BM25_OK)
                goto failed;
            posting->ordinal = kc_bm25_read32(item);
            posting->frequency = kc_bm25_read32(item + 4);
            if (posting->ordinal >= docs || posting->frequency == 0 ||
                (j != 0 && posting->ordinal <= previous) ||
                lengths[posting->ordinal] + posting->frequency >
                index->documents[posting->ordinal].length)
                goto failed;
            lengths[posting->ordinal] += posting->frequency;
            previous = posting->ordinal;
            index->posting_count++;
        }
    }
    if (reader.remaining != 0) goto failed;
    for (size_t i = 0; i < index->document_count; i++) {
        if (lengths[i] != index->documents[i].length)
            goto failed;
    }
    index->total_tokens = total;
    index->built = 1;
    index->read_only = 1;
    *out = index;
    index = NULL;
    status = KC_BM25_OK;

failed:
    free(lengths);
    kc_bm25_close(index);
    return status;
}

/**
 * Persist an exported index to a binary file.
 * @param index Index to save.
 * @param path Destination path.
 * @return KC_BM25_OK or an error status.
 */
int kc_bm25_save(const kc_bm25_t *index, const char *path)
{
    void *buffer = NULL;
    size_t size = 0;
    FILE *file;
    int status;

    if (index == NULL || path == NULL || path[0] == '\0')
        return KC_BM25_EINVAL;
    status = kc_bm25_export(index, &buffer, &size);
    if (status != KC_BM25_OK) return status;
    file = fopen(path, "wb");
    if (file == NULL) {
        kc_bm25_free(buffer);
        return KC_BM25_EIO;
    }
    status = fwrite(buffer, 1, size, file) == size ?
        KC_BM25_OK : KC_BM25_EIO;
    if (fclose(file) != 0) status = KC_BM25_EIO;
    kc_bm25_free(buffer);
    return status;
}

/**
 * Load a binary index file through the same memory-import contract.
 * @param out Receives the loaded index.
 * @param path Source index path.
 * @return KC_BM25_OK or an error status.
 */
int kc_bm25_load(kc_bm25_t **out, const char *path)
{
    unsigned char *buffer = NULL;
    FILE *file;
    long length;
    int status;

    if (out == NULL) return KC_BM25_EINVAL;
    *out = NULL;
    if (path == NULL || path[0] == '\0') return KC_BM25_EINVAL;
    file = fopen(path, "rb");
    if (file == NULL) return KC_BM25_EIO;
    if (fseek(file, 0, SEEK_END) != 0 ||
        (length = ftell(file)) < 0 ||
        fseek(file, 0, SEEK_SET) != 0) {
        fclose(file);
        return KC_BM25_EIO;
    }
    buffer = (unsigned char *)malloc(length == 0 ? 1 : (size_t)length);
    if (buffer == NULL) {
        fclose(file);
        return KC_BM25_ENOMEM;
    }
    if (fread(buffer, 1, (size_t)length, file) != (size_t)length) {
        free(buffer);
        fclose(file);
        return KC_BM25_EIO;
    }
    if (fclose(file) != 0) {
        free(buffer);
        return KC_BM25_EIO;
    }
    status = kc_bm25_import(out, buffer, (size_t)length);
    free(buffer);
    return status;
}

/**
 * Get the number of indexed documents.
 * @param index Index handle.
 * @return Number of documents or zero for NULL.
 */
size_t kc_bm25_count(const kc_bm25_t *index) {
    return index == NULL ? 0 : index->document_count;
}

/**
 * Get the selected accent-folding mode.
 * @param index Index handle.
 * @return One for enabled accent folding, otherwise zero.
 */
int kc_bm25_fold_accents(const kc_bm25_t *index) {
    return index == NULL ? 0 : index->fold_accents;
}

/**
 * Release a returned result array.
 * @param results Caller-owned result array.
 * @return None.
 */
void kc_bm25_free(void *results) {
    free(results);
}

/**
 * Release the index, its document storage, and its inverted index.
 * @param index Index handle.
 * @return None.
 */
void kc_bm25_close(kc_bm25_t *index) {
    if (index == NULL) return;
    kc_bm25_clear_postings(index);
    for (size_t i = 0; i < index->document_count; i++) {
        free(index->documents[i].id);
        free(index->documents[i].content);
    }
    free(index->documents);
    free(index);
}

/**
 * Get an explanatory status description.
 * @param status Library status.
 * @return Static status text.
 */
const char *kc_bm25_strerror(int status) {
    switch (status) {
        case KC_BM25_OK: return "Success";
        case KC_BM25_EINVAL: return "Invalid argument";
        case KC_BM25_ENOMEM: return "Insufficient memory";
        case KC_BM25_ESTATE: return "Index state does not allow this operation";
        case KC_BM25_EIO: return "File I/O failed";
        case KC_BM25_EFORMAT: return "Invalid or incompatible index file";
        case KC_BM25_EUTF8: return "Malformed UTF-8 text";
        case KC_BM25_EABORT: return "Traversal stopped by callback";
        default: return "Unknown BM25 error";
    }
}

/**
 * Return the generated build timestamp.
 * @return Unix timestamp or zero when unspecified.
 */
uint64_t kc_bm25_version(void) {
    return (uint64_t)KC_BM25_BUILD_VERSION;
}
